"""Import a verified batch of attractions from public sources.

This maintenance command is deliberately independent of Amap.  Candidates
are hand-selected from public tourism/encyclopedia lists for cities that need
additional verified coverage (including cities that already have rows).  A
candidate is imported only when both checks pass:

* a location-relevant public description is available from Baidu Baike or a
  manually verified government/official source; and
* a city-scoped public map object (OSM, Baidu Maps MCP, or Wikidata) identifies
  the named attraction in that city (used for the real coordinates).

OSM coordinates are WGS-84 and Baidu Maps coordinates are BD-09. Mainland
coordinates are locally converted to GCJ-02 before storage; Hong Kong, Macao,
and Taiwan coordinates remain WGS-84.
The source values and stored-coordinate system remain in the JSON audit. No
Amap conversion/API call is made.

The database schema is intentionally unchanged.  Preview is the default;
``--commit`` writes rows and an audit file under ``data/imports``.  Coordinate
and description source URLs are kept in that audit file rather than added as
database columns, in line with the project's attraction-table decision.
"""

