USER_AGENT = "travel-agent-public-data-audit/1.0 (https://github.com/openai)"
NOMINATIM_URL = "https://nominatim.openstreetmap.org/search"
NOMINATIM_MIN_INTERVAL = 1.05  # public service policy: max about one request/sec


def wgs84_to_gcj02(
    longitude: float,
    latitude: float,
    *,
    province: str | None = None,
) -> tuple[float, float]:
    """Convert mainland WGS-84 coordinates locally, leaving HK/Macao/Taiwan unchanged."""
    if province in {"香港特别行政区", "澳门特别行政区", "台湾省"}:
        return longitude, latitude
    if not (72.004 <= longitude <= 137.8347 and 0.8293 <= latitude <= 55.8271):
        return longitude, latitude

    def transform_lat(x: float, y: float) -> float:
        value = -100.0 + 2.0 * x + 3.0 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * math.sqrt(abs(x))
        value += (20.0 * math.sin(6.0 * x * math.pi) + 20.0 * math.sin(2.0 * x * math.pi)) * 2.0 / 3.0
        value += (20.0 * math.sin(y * math.pi) + 40.0 * math.sin(y / 3.0 * math.pi)) * 2.0 / 3.0
        value += (160.0 * math.sin(y / 12.0 * math.pi) + 320.0 * math.sin(y * math.pi / 30.0)) * 2.0 / 3.0
        return value

    def transform_lng(x: float, y: float) -> float:
        value = 300.0 + x + 2.0 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * math.sqrt(abs(x))
        value += (20.0 * math.sin(6.0 * x * math.pi) + 20.0 * math.sin(2.0 * x * math.pi)) * 2.0 / 3.0
        value += (20.0 * math.sin(x * math.pi) + 40.0 * math.sin(x / 3.0 * math.pi)) * 2.0 / 3.0
        value += (150.0 * math.sin(x / 12.0 * math.pi) + 300.0 * math.sin(x / 30.0 * math.pi)) * 2.0 / 3.0
        return value

    semi_major_axis = 6378245.0
    eccentricity_sq = 0.00669342162296594323
    d_lat = transform_lat(longitude - 105.0, latitude - 35.0)
    d_lng = transform_lng(longitude - 105.0, latitude - 35.0)
    rad_lat = latitude / 180.0 * math.pi
    sin_lat = math.sin(rad_lat)
    magic = 1.0 - eccentricity_sq * sin_lat * sin_lat
    sqrt_magic = math.sqrt(magic)
    d_lat = d_lat * 180.0 / ((semi_major_axis * (1.0 - eccentricity_sq)) / (magic * sqrt_magic) * math.pi)
    d_lng = d_lng * 180.0 / (semi_major_axis / sqrt_magic * math.cos(rad_lat) * math.pi)
    return longitude + d_lng, latitude + d_lat


def bd09_to_gcj02(longitude: float, latitude: float) -> tuple[float, float]:
    """Convert Baidu BD-09LL coordinates to the GCJ-02 used by the app maps."""
    x = longitude - 0.0065
    y = latitude - 0.006
    z = math.sqrt(x * x + y * y) - 0.00002 * math.sin(y * math.pi * 3000.0 / 180.0)
    theta = math.atan2(y, x) - 0.000003 * math.cos(x * math.pi * 3000.0 / 180.0)
    return z * math.cos(theta), z * math.sin(theta)

